package kr.tong.sky;
import android.content.Context;import android.database.Cursor;import org.json.*;import java.time.*;import java.util.*;

/** Counts route/dates with public markers, not seats or passengers. */
final class DashboardStats {
 static final class Counts {final int[] values=new int[3];int observed=0,months=0;long latest=0;void add(Counts c){if(c==null)return;observed+=c.observed;months+=c.months;latest=Math.max(latest,c.latest);for(int i=0;i<3;i++)values[i]+=c.values[i];}}
 final Map<String,Counts> airports=new HashMap<>();long latest=0;LocalDate nearest;String nearestRoute="";
 Counts airport(String code){Counts count=airports.get(code);return count==null?new Counts():count;}
 int totalMarks(String code){Counts count=airports.get(code);return count==null?0:count.values[0]+count.values[1]+count.values[2];}
 Counts region(JSONArray cities)throws Exception{Counts all=new Counts();for(int i=0;i<cities.length();i++)all.add(airports.get(cities.getJSONObject(i).getString("code")));return all;}
 static DashboardStats load(Context ctx,String anchor)throws Exception{return load(ctx,anchor,false);}
 static DashboardStats load(Context ctx,String anchor,boolean oz)throws Exception{DashboardStats stats=new DashboardStats();LocalDate today=Search.today(),last=Search.lastDate(oz);try(SkyDb db=new SkyDb(ctx,oz);RepeatMarkerHistory history=new RepeatMarkerHistory(ctx);Cursor rows=db.getReadableDatabase().rawQuery("SELECT data,success FROM snapshots WHERE k LIKE ? OR k LIKE ?",new String[]{anchor+"-%","%-"+anchor+"-%"})){ReferenceMarkerRules.Context references=new ReferenceMarkerRules.Context();if(!oz){while(rows.moveToNext())references.add(new JSONObject(rows.getString(0)),rows.getLong(1));rows.moveToPosition(-1);}while(rows.moveToNext()){if(Thread.currentThread().isInterrupted())throw new InterruptedException();JSONObject raw=new JSONObject(rows.getString(0));if(!RegionScope.allowed(raw,anchor))continue;JSONObject current=oz?RouteWeekdayFilter.apply(raw):RepeatMarkerPolicy.usesCalendar(raw)?RepeatMarkerPolicy.calendar(raw,references):RouteWeekdayFilter.apply(db.operationPolicy.snapshot(raw));if(oz)AsianaData.validate(current,current);else history.record(current,rows.getLong(1));YearMonth savedMonth=YearMonth.parse(current.getString("month"));if(savedMonth.isBefore(YearMonth.from(today))||savedMonth.isAfter(YearMonth.from(last)))continue;String origin=current.getString("origin"),destination=current.getString("destination");if(!anchor.equals(origin)&&!anchor.equals(destination))continue;String other=anchor.equals(origin)?destination:origin;Counts count=stats.airports.computeIfAbsent(other,k->new Counts());count.months++;count.latest=Math.max(count.latest,rows.getLong(1));stats.latest=Math.max(stats.latest,rows.getLong(1));JSONArray days=current.getJSONArray("dates");for(int i=0;i<days.length();i++){JSONObject day=days.getJSONObject(i);LocalDate date=LocalDate.parse(day.getString("date"));if(date.isBefore(today)||date.isAfter(last)||!SeatMarks.verified(day,oz))continue;count.observed++;for(int marker=0;marker<3;marker++)if(SeatMarks.marked(day,SeatMarks.FIELDS[marker],oz))count.values[marker]++;if(SeatMarks.available(day,0,oz)&&(stats.nearest==null||date.isBefore(stats.nearest))){stats.nearest=date;stats.nearestRoute=origin+" → "+destination;}}}}return stats;}
}
